def policy(obs, P):
    x = obs[0]
    v = obs[1]
    th = obs[2]
    w = obs[3]
    if x <= P['x_thr_left']:
        return 1
    if x >= P['x_thr_right']:
        return 0
    if w <= P['w_thr_low']:
        if th > P['th_thr_high']:
            return 1
        if v > P['v_thr_high']:
            return 1
        return 0
    if th <= P['th_thr_neg'] and v <= P['v_thr_low'] and w <= P['w_thr_mid']:
        return 0
    score = P['k_th']*th + P['k_w']*w + P['k_x']*x + P['k_v']*v + P['bias']
    return 1 if score > P['thr'] else 0

